ble .time-slot {\n          color: #e5e7eb;\n        }\n\n        @media (max-width: 767px) {\n          .conference-schedule-wrap {\n            display: none;\n          }\n\n          .conference-mobile-schedule {\n            display: grid;\n            gap: 12px;\n          }\n\n          .conference-mobile-day {\n            border: 1px solid #d9dee6;\n            background: #dfe8f2;\n            padding: 14px;\n            text-align: center;\n            font-weight: 600;\n            color: #151922;\n          }\n\n          .conference-mobile-slot {\n            overflow: hidden;\n            border: 1px solid #d9dee6;\n            background: #ffffff;\n          }\n\n          .conference-mobile-time {\n            background: #dfe8f2;\n            padding: 10px 14px;\n            font-size: 13px;\n            font-weight: 600;\n            color: #151922;\n          }\n\n          .conference-mobile-room {\n            border-top: 1px solid #d9dee6;\n            padding: 12px 14px;\n          }\n\n          .conference-mobile-room span {\n            display: block;\n            margin-bottom: 4px;\n            font-size: 11px;\n            font-weight: 700;\n            letter-spacing: 0;\n            color: #64748b;\n          }\n\n          .conference-mobile-room p {\n            margin: 0;\n            overflow-wrap: anywhere;\n            font-size: 14px;\n            line-height: 1.35;\n            color: #333333;\n          }\n\n          .conference-mobile-room .session-strong {\n            font-weight: 700;\n          }\n\n          .dark .conference-mobile-day,\n          .dark .conference-mobile-time {\n            border-color: #334155;\n            background: #243244;\n            color: #f8fafc;\n          }\n\n          .dark .conference-mobile-slot {\n            border-color: #334155;\n            background: #111827;\n          }\n\n          .dark .conference-mobile-room {\n            border-color: #334155;\n          }\n\n       